import { createContext, useState, useEffect } from 'react';
import axios from 'axios';

export const AuthContext = createContext();

export const AuthContextProvider = ({ children }) => {
  const [currentUser, setCurrentUser] = useState(null);
  const [token, setToken] = useState(sessionStorage.getItem('token') || null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const storedUser = sessionStorage.getItem('user');
    const storedToken = sessionStorage.getItem('token');
    if (storedUser && storedToken) {
      console.log('Initializing user from sessionStorage:', JSON.parse(storedUser));
      const user = JSON.parse(storedUser);
      setCurrentUser(user);
      setToken(storedToken);
      // Verify token
      axios
        .get('http://localhost:5000/api/users/me', {
          headers: { Authorization: `Bearer ${storedToken}` },
        })
        .then((res) => {
          console.log('Verified user:', res.data);
          setCurrentUser(res.data);
          sessionStorage.setItem('user', JSON.stringify(res.data));
        })
        .catch((err) => {
          console.error('Token verification failed:', err);
          setCurrentUser(null);
          setToken(null);
          sessionStorage.removeItem('user');
          sessionStorage.removeItem('token');
          setError('Session expired. Please log in again.');
        });
    }
  }, []);

  const login = async (username, password) => {
    try {
      setError(null);
      console.log('Sending login request:', { username });
      const res = await axios.post('http://localhost:5000/api/auth/login', {
        username,
        password,
      });
      console.log('Login response:', res.data);
      const { user, token } = res.data;
      setCurrentUser(user);
      setToken(token);
      sessionStorage.setItem('user', JSON.stringify(user));
      sessionStorage.setItem('token', token);
      return true;
    } catch (err) {
      const message = err.response?.data?.message || 'Login failed';
      console.error('Login error:', err.response?.data || err);
      setError(message);
      throw new Error(message);
    }
  };

  const logout = () => {
    setCurrentUser(null);
    setToken(null);
    setError(null);
    sessionStorage.removeItem('user');
    sessionStorage.removeItem('token');
  };

  return (
    <AuthContext.Provider
      value={{ currentUser, setCurrentUser, token, login, logout, error }}
    >
      {children}
    </AuthContext.Provider>
  );
};
